@startuml

class Well {
  + code : string
  + pollutionRate() : float
}

class OnshoreWell extends Well {
  + surfaceExtension : float
}

class OffshoreWell extends Well {
  + yearOfInstallation : int
  + pollutionRate() : float
}

class Company {
  + taxCode : string
  + numberOfEmployees : int
}

class Area {
  + code : string
  + environmentalImportance : int
}

class Extraction {
  + quantity : float
}

Well "1" -- "*" Extraction
Extraction "*" -- "1" Company
Well "0..1" -- "0..1" OffshoreWell : is
OffshoreWell "*" -- "0..1" Area : located in
Extraction "1" -- "1" Well
Extraction "1" -- "1" Company

@enduml

